using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

public class Turn : ScriptableObject
{
	[Header("Event")]
	[SerializeField]
	private StringEvent OnTurnChange;

	[SerializeField]
	private string turnName;

	[SerializeField]
	private VoidEvent OnStartTurnEvent;

	[Header("Turn Panel")]
	[SerializeField]
	private TurnPanelStatesData turnPanelStatesData;

	public TurnPanelStatesData TurnPanelStatesData => turnPanelStatesData;

	public virtual void OnStartTurn()
	{
		OnStartTurnEvent?.Raise();
		Debug.Log("On Start Turn: " + base.name);
		SetTurnName();
	}

	public virtual void OnEndTurn()
	{
	}

	public void SetTurnName()
	{
		if (turnName != "")
		{
			OnTurnChange.Raise(turnName);
		}
	}
}
